// ---------------------------------------------------------------- Whisper Woods
function forestRegion(game, U, r, inner, outer) {
  const W = game.world;
  const bigTree = (g, x, z, o) => { const t = makeBigTree(r, o); placeT(g, U, t, x, z, 0); const [w] = t.userData.col; boxT(g, x, z, w * 0.7, 9, w * 0.7, { cam: false }); return t; };
  U.push(fillRing(game, r, { inner, outer, count: 1100, pad: 9, claim: 5, range: 170, kinds: [
    { w: 8, build: (g, r, x, z) => blob(r, x, z, 11, r.int(3, 7), (cx, cz) => bigTree(g, cx, cz, { simple: r.chance(0.6), lanterns: r.chance(0.12) })) },
    { w: 3, build: (g, r, x, z) => blob(r, x, z, 8, r.int(4, 9), (cx, cz) => { const s = r.range(0.4, 2.6); const m = makeMushroom(s, r.pick([0, 20, 200, 300, 40]), r, r.chance(0.5)); placeT(g, U, m, cx, cz, 0); if (m.userData.update) U.push(m.userData.update); if (s > 1.4) boxT(g, cx, cz, 0.5 * s, 1.3 * s, 0.5 * s, { cam: false }); }) },
    { w: 3, build: (g, r, x, z) => makeFerns(g, [[x, z, 14, 40]], r) },
    { w: 2, build: (g, r, x, z) => blob(r, x, z, 6, r.int(2, 4), (cx, cz) => { placeT(g, U, makeStump(r), cx, cz, r() * TAU); boxT(g, cx, cz, 1.0, 0.75, 1.0, { cam: false }); }) },
    { w: 2, build: (g, r, x, z) => { placeT(g, U, makeHollowLog(r), x, z, r() * TAU); boxT(g, x, z, 1.4, 1.2, 1.4, { cam: false }); } },
    { w: 2, build: (g, r, x, z) => blob(r, x, z, 7, r.int(2, 5), (cx, cz) => placeT(g, U, makeRock(r, 0x6b7a6a, r.range(1.0, 2.4)), cx, cz, 0)) },
    { w: 1, build: (g, r, x, z) => { U.push(makeGlowPond(g, x, z, r.range(3.5, 6), r).userData.update); blob(r, x, z, 9, 8, (cx, cz) => { const m = makeMushroom(r.range(0.4, 0.8), r.pick([0, 300, 200]), r, true); placeT(g, U, m, cx, cz, 0); if (m.userData.update) U.push(m.userData.update); }); } },
    { w: 1, build: (g, r, x, z) => { const a = r() * TAU, bx = x + cos(a) * 16, bz = z + sin(a) * 16; bigTree(g, x, z, { lanterns: true }); bigTree(g, bx, bz, { lanterns: true }); U.push(makeLanternString(g, x, z, bx, bz, 7, 4.2).update); } },
  ] }));
  // Round 817/818's census found the same gap a third time: these fourteen deer/fox/butterfly picks
  // are `fillRing`'s own outer-country population, not the hand-built glade trio this log already
  // befriended one at a time (rounds 1, 2, 3 above). `makeDeer()`'s rig carries none of
  // `.look`/`.robot`/`.cookie`, so `Wanderer`'s own `greetable()` call quietly no-ops on every one of
  // these too. The first of the fourteen (i===0, always a deer since the loop starts on that branch)
  // now answers "Say hello to the deer" too, same `game.namedFriend` + `game.addInteractable` fix as
  // the outer crab and penguin, keyed straight to its own `rig.group` so the prompt follows it through
  // its usual 11 m leash — wired up after the `Wanderer` already exists, so it draws nothing extra from
  // this world's own seeded `r()` and shifts no later pick in this build. No new mesh, no new physics
  // box. The other thirteen are being closed one at a time, same pattern as everywhere else; as of this
  // round, deer i=12, fox i=10,13 and butterfly i=11 are what's left.
  for (let i = 0; i < 14; i++) {
    const a = r() * TAU, d = r.range(inner, outer * 0.85), x = cos(a) * d, z = sin(a) * d;
    if (i % 3 === 0) {
      const rig = makeDeer(); W.add(rig.group);
      game.npcs.push(new Wanderer(game, rig, { x, z, speed: 0.6, leash: 11, r: 0.45, height: 1.4, step: 0.3, idle: [3, 7], walk: [2, 5] }));
      if (i === 0) {
        const outerDeerId = game.namedFriend('outer-deer');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the deer', onUse: () => {
          game.befriend(outerDeerId); SFX.rustle(); game.hearts(rig.group.position.x, 1.1, rig.group.position.z, 3);
          game.toast('🦌 "*freezes mid-chew, ears swivelling, then bolts three bounds into the ferns*"'); } });
      }
      // Round 821's fox closed the i%3===1 branch's first pick; this is the i%3===0 branch's own second
      // deer (i===3, the next multiple of three after round 819's i===0), left just as unmet by the same
      // `makeDeer()` rig with none of `.look`/`.robot`/`.cookie` that `Wanderer`'s own `greetable()`
      // quietly skips. Same fix, a second distinct id so it stacks with the first rather than replacing
      // it, and a calmer line since this one only lifts its head rather than bolting outright.
      else if (i === 3) {
        const outerDeer2Id = game.namedFriend('outer-deer-2');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the deer', onUse: () => {
          game.befriend(outerDeer2Id); SFX.rustle(); game.hearts(rig.group.position.x, 1.1, rig.group.position.z, 3);
          game.toast('🦌 "*lifts its head, chews once more, then steps unhurried behind a fern*"'); } });
      }
      // The i%3===0 branch's third deer (i===6, the next multiple of three after rounds 819/822's
      // i===0 and i===3), left just as unmet by the same `makeDeer()` rig with none of
      // `.look`/`.robot`/`.cookie` that `Wanderer`'s own `greetable()` quietly skips. Same fix, a
      // third distinct id so it stacks with the first two, and a wary line of its own: this one
      // backs away a few steps before it turns, rather than bolting or merely stepping behind a fern.
      else if (i === 6) {
        const outerDeer3Id = game.namedFriend('outer-deer-3');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the deer', onUse: () => {
          game.befriend(outerDeer3Id); SFX.rustle(); game.hearts(rig.group.position.x, 1.1, rig.group.position.z, 3);
          game.toast('🦌 "*backs away three slow steps, never taking its eyes off the cat, then turns and ambles into the ferns*"'); } });
      }
      // The i%3===0 branch's fourth deer (i===9, the next multiple of three after rounds 819/822/here's
      // i===0, i===3 and i===6), left just as unmet by the same `makeDeer()` rig with none of
      // `.look`/`.robot`/`.cookie` that `Wanderer`'s own `greetable()` quietly skips. Same fix, a
      // fourth distinct id so it stacks with the first three, and a line of its own: this one keeps
      // eating and only flicks an ear, rather than bolting, stepping away or backing off.
      else if (i === 9) {
        const outerDeer4Id = game.namedFriend('outer-deer-4');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the deer', onUse: () => {
          game.befriend(outerDeer4Id); SFX.rustle(); game.hearts(rig.group.position.x, 1.1, rig.group.position.z, 3);
          game.toast('🦌 "*keeps right on eating, only flicking one ear toward the cat to show it noticed*"'); } });
      }
    }
    else if (i % 3 === 1) {
      const rig = makeFox(); W.add(rig.group);
      game.npcs.push(new Wanderer(game, rig, { x, z, speed: 1.3, leash: 12, r: 0.3, height: 0.8, step: 0.3, idle: [1, 3], walk: [2, 5] }));
      // Round 814's deer closed the i%3===0 branch of this same loop; this is the i%3===1 branch's own
      // first fox (i===1), still as unmet as the deer was — `makeFox()`'s rig carries none of
      // `.look`/`.robot`/`.cookie` either, so `Wanderer`'s own `greetable()` call quietly no-ops on it
      // same as everywhere else in this log. Same fix, same `SFX.bark()` the den foxes and the bold fox
      // already use for their own greets: `game.namedFriend('outer-fox')` plus a `game.addInteractable`
      // keyed straight to the rig's own `group`, wired up after the `Wanderer` already exists so it draws
      // nothing extra from this world's own seeded `r()` and shifts no later pick in this build. No new
      // mesh, no new physics box — this fox was already wandering its usual 12 m leash.
      if (i === 1) {
        const outerFoxId = game.namedFriend('outer-fox');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the fox', onUse: () => {
          game.befriend(outerFoxId); SFX.bark(); game.hearts(rig.group.position.x, 0.6, rig.group.position.z, 3);
          game.toast('🦊 "*freezes, one paw raised, eyes fixed on the cat, then slips off through the ferns*"'); } });
      }
      // Round 821 closed the i%3===1 branch's first fox (i===1); this is the branch's own second
      // (i===4, the next multiple-of-three-plus-one), left just as unmet by the same `makeFox()` rig
      // with none of `.look`/`.robot`/`.cookie` that `Wanderer`'s own `greetable()` quietly skips. Same
      // fix, a second distinct id so it stacks with the first rather than replacing it, and a bolder
      // line since this one bolts outright rather than freezing first.
      else if (i === 4) {
        const outerFox2Id = game.namedFriend('outer-fox-2');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the fox', onUse: () => {
          game.befriend(outerFox2Id); SFX.bark(); game.hearts(rig.group.position.x, 0.6, rig.group.position.z, 3);
          game.toast('🦊 "*ears snap back, then bolts in a streak of orange toward the undergrowth*"'); } });
      }
      // Round 821 and the round above closed the i%3===1 branch's first two foxes (i===1, i===4); this
      // is the branch's own third (i===7, the next multiple-of-three-plus-one), left just as unmet by
      // the same `makeFox()` rig with none of `.look`/`.robot`/`.cookie` that `Wanderer`'s own
      // `greetable()` quietly skips. Same fix, a third distinct id so it stacks with the first two, and
      // a curious line of its own: this one approaches a step before it decides against it, rather than
      // freezing first or bolting outright.
      else if (i === 7) {
        const outerFox3Id = game.namedFriend('outer-fox-3');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the fox', onUse: () => {
          game.befriend(outerFox3Id); SFX.bark(); game.hearts(rig.group.position.x, 0.6, rig.group.position.z, 3);
          game.toast('🦊 "*takes one curious step closer, sniffs the air, then thinks better of it and trots away*"'); } });
      }
    }
    else {
      const rig = makeButterfly(r.pick([300, 40, 200, 20, 260]));
      game.npcs.push(new Flyer(game, rig, { cx: x, cz: z, r: r.range(2, 5), h: r.range(0.8, 2.4), speed: r.range(0.8, 1.6), bob: 0.3, wobble: 0.8, cw: i % 2 === 0 }));
      // This loop's four butterflies (i%3===2: i=2,5,8,11) have only ever been ambient decoration —
      // unlike the deer and fox branches above, nothing here ever gave them a `game.namedFriend` id,
      // so none of this log's "Say hello" fixes applied to a flying creature yet. `Flyer` already
      // calls `game.world.add(rig.group)` itself in its own constructor, so the rig needs no extra
      // wiring to satisfy the scene-graph check; only the interactable is new. The proximity test in
      // `80-game.js` compares `pos.x/z` only, never height, so the usual 2.1 m radius still catches
      // the cat passing underneath while this one loops 0.8–2.4 m up — no need to wait for it to
      // land, since it never does. First of the four (i===2) now answers "Say hello to the
      // butterfly", with `SFX.twinkle()` instead of any of this log's bark/click/squawk since nothing
      // here has a voice to begin with.
      if (i === 2) {
        const outerButterflyId = game.namedFriend('outer-butterfly');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the butterfly', onUse: () => {
          game.befriend(outerButterflyId); SFX.twinkle(); game.hearts(rig.group.position.x, rig.group.position.y, rig.group.position.z, 3);
          game.toast('🦋 "*wings flutter in a tight loop around the cat\'s head, then drifts off over the ferns*"'); } });
      }
      // Round 826 closed this loop's first butterfly (i===2); this is its second (i===5, the next
      // i%3===2 pick), left just as unmet by the same `makeButterfly()` rig that nothing had ever given
      // a `game.namedFriend` id. Same fix, a second distinct id so it stacks with the first rather than
      // replacing it, and a line of its own: this one settles on the cat's head a moment rather than
      // only looping around it.
      else if (i === 5) {
        const outerButterfly2Id = game.namedFriend('outer-butterfly-2');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the butterfly', onUse: () => {
          game.befriend(outerButterfly2Id); SFX.twinkle(); game.hearts(rig.group.position.x, rig.group.position.y, rig.group.position.z, 3);
          game.toast('🦋 "*lands on the cat\'s head for a moment, then flits off toward the glow pond*"'); } });
      }
      // Round 831 closed this loop's second butterfly (i===5); this is its third (i===8, the next
      // i%3===2 pick), left just as unmet by the same `makeButterfly()` rig that nothing had ever given
      // a `game.namedFriend` id. Same fix, a third distinct id so it stacks with the first two rather
      // than replacing either, and a line of its own: this one keeps its distance and only dips lower on
      // its loop, rather than circling the cat's head or landing on it.
      else if (i === 8) {
        const outerButterfly3Id = game.namedFriend('outer-butterfly-3');
        game.addInteractable({ obj: rig.group, radius: 2.1, label: () => 'Say hello to the butterfly', onUse: () => {
          game.befriend(outerButterfly3Id); SFX.twinkle(); game.hearts(rig.group.position.x, rig.group.position.y, rig.group.position.z, 3);
          game.toast('🦋 "*dips low on its loop for just a moment, wings catching the light, then rises back out of reach*"'); } });
      }
    }
  }
}
